113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = normalizeAddress(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setTelephone(telephone);
128	        if (owner.getEmail() != null) {
129	            String email = normalizeEmail(owner.getEmail());
130	            if (email == null) {
131	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	            }
133	            owner.setEmail(email);
134	        }
135	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
139	        if (effectiveRegistrationDate == null) {
140	            effectiveRegistrationDate = LocalDate.now();
141	        }
142	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
143	        owner.setRegistrationDate(registrationDate);
144	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
145	            return new ResponseEntity<>(HttpStatus.CONFLICT);
146	        }
147	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
148	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
149	        }
150	        // Owners sharing a household (same normalized last name and address) are given a
151	        // stable shared householdId, which forms the household component of the identityKey.
152	        String lastNameKey = householdKey(owner.getLastName());
153	        String addressKey = householdKey(owner.getAddress());
154	        List<Owner> householdMembers = new ArrayList<>();
155	        for (Owner existing : this.clinicService.findAllOwners()) {
156	            if (lastNameKey.equals(householdKey(existing.getLastName()))
157	                && addressKey.equals(householdKey(existing.getAddress()))) {
158	                householdMembers.add(existing);
159	            }
160	        }
161	        if (!householdMembers.isEmpty()) {
162	            String householdId = householdId(lastNameKey, addressKey);
163	            owner.setHouseholdId(householdId);
164	            for (Owner member : householdMembers) {
165	                if (!householdId.equals(member.getHouseholdId())) {
166	                    member.setHouseholdId(householdId);
167	                    this.clinicService.saveOwner(member);
168	                }
169	            }
170	        }
171	        // Consolidated duplicate detection: reject only when the whole identityKey
172	        // (normalized telephone | email | householdId) matches an existing owner's.
173	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
174	        for (Owner existing : this.clinicService.findAllOwners()) {
175	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
176	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
177	                return new ResponseEntity<>(HttpStatus.CONFLICT);
178	            }
179	        }
180	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
181	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        this.clinicService.saveOwner(owner);
184	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
185	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
187	            ownerDto.getMembershipLevel());
188	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
189	        headers.setLocation(UriComponentsBuilder.newInstance()
190	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
191	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
192	    }
